#Region @DOC
#### Description:
#Runs a TI process on another database over the REST API (`tm1.ExecuteWithReturn`). If the process does not exist on the target database, it is first copied from the source database with `}bedrock.migrate.process`.
#
#### How to Use:
#
#- `pProcess`: REQUIRED: the name of the process to run.
#- `pProcessParameters`: OPTIONAL: a JSON Object of parameter values for the process, e.g. `{"pCube": "Sales", "pLogOutput": 1}`.
#- `pTargetDatabaseName`: REQUIRED: the database the process runs on.
#- `pSourceDatabaseName`: REQUIRED: the database the process is copied from if it does not exist on the target.
#- Both are connection names, or connection-details JSON objects.
#- `pLogOutput`, `pStrictErrorHandling` and `pJson` work as in all bedrock processes.
#
#### Return Value:
#`sBedrockReturnValue` is set to the `ExecuteWithReturn` response, with `/response_body/ErrorLogFile` simplified to the error log file name.
#
#Here is an example call:
#```
#ExecuteProcess( '}bedrock.process.execute_externally',
#  'pProcess', '}bedrock.cube.data.clear',
#  'pProcessParameters', '{"pCube": "Sales"}',
#  'pSourceDatabaseName', 'Development',
#  'pTargetDatabaseName', 'UAT' );
#```
#EndRegion @DOC

### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );

### Constants ###
cThisProcName   = GetProcessName();
cUserName       = TM1User();
cTimeStamp      = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt      = NumberToString( INT( RAND( ) * 1000000000 ));
cTemp           = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
sMessages       = '{"Process": "'|cThisProcName|'", "User": "'|cUsername|'", "Info": ["Process: '''|cThisProcName|''' run by User: '''|cUsername|'''."], "Error": []}';

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );
sMessages = '{"Process": "'|GetProcessName()|'", "User": "'|TM1User()|'", "Info": ["Process: '''|GetProcessName()|''' run by User: '''|TM1User()|'''."], "Error": []}';
pDefaultParameters = '{
  "pProcess":             null,
  "pProcessParameters":   "",
  "pSourceDatabaseName":  null,
  "pTargetDatabaseName":  null,
  "pLogOutput":           0,
  "pStrictErrorHandling": 0
}';

pPassedParameters = '{
  "pProcess":             '|StringToJson  ( pProcess             )|',
  "pProcessParameters":   '|StringToJson  ( pProcessParameters   )|',
  "pSourceDatabaseName":  '|StringToJson  ( pSourceDatabaseName  )|',
  "pTargetDatabaseName":  '|StringToJson  ( pTargetDatabaseName  )|',
  "pLogOutput":           '|NumberToString( pLogOutput           )|',
  "pStrictErrorHandling": '|NumberToString( pStrictErrorHandling )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );
# String Parameters
pProcess             =                 JsonToString( pJson, '/pProcess'             );
IF( JsonType( JsonGet( pJson, '/pProcessParameters' ) ) @= 'string' );
  pProcessParameters = JsonToString( pJson, '/pProcessParameters' );
ELSE;
  pProcessParameters = JsonGet( pJson, '/pProcessParameters' );
ENDIF;
IF( JsonType( JsonGet( pJson, '/pSourceDatabaseName' ) ) @= 'string' );
  pSourceDatabaseName = JsonToString( pJson, '/pSourceDatabaseName' );
ELSE;
  pSourceDatabaseName = JsonGet( pJson, '/pSourceDatabaseName' );
ENDIF;
IF( JsonType( JsonGet( pJson, '/pTargetDatabaseName' ) ) @= 'string' );
  pTargetDatabaseName = JsonToString( pJson, '/pTargetDatabaseName' );
ELSE;
  pTargetDatabaseName = JsonGet( pJson, '/pTargetDatabaseName' );
ENDIF;
# Numeric Parameters
pLogOutput           = StringToNumber( JsonToString( pJson, '/pLogOutput'           ) );
pStrictErrorHandling = StringToNumber( JsonToString( pJson, '/pStrictErrorHandling' ) );

### Get the parameters that differ from the default
pDiffer = JsonDiff( pDefaultParameters, pJson );
nSize = JsonSize( pDiffer );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  pDiffer = JsonReplace( pDiffer, '/'|NumberToString( nSize )|'/op', '"add"' );
END;
pJson = JsonPatch( '{}', pDiffer );

### LogOutput parameters
nSize = JsonSize( pJson );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  sKey = JsonGetKey( pJson, nSize );
  pPassedParameters = JsonReplace( pPassedParameters, sKey, JsonGet( pJson, sKey ) );
END;

sMessages = JsonAdd( sMessages, '/Info/0', pPassedParameters );
IF( pLogOutput = 1 );
  LogOutput('INFO', JsonToString( sMessages, '/Info/0' ) );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################
#################################################################################################
#Region - Validate Parameters

IF( pProcess @= '' );
  sMessages = JsonAdd( sMessages, '/Error/0', '"pProcess is required."' );
ENDIF;

# Get Database Connection Details
sSourceDatabaseParameterType = JsonType( pSourceDatabaseName );
IF( sSourceDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.session.start', 'pConnectionName', pSourceDatabaseName, 'pJson', pJson ); sSourceConnectionDetails = sBedrockReturnValue;
ELSE;
  sSourceConnectionDetails = pSourceDatabaseName;
ENDIF;
pJson = JsonAdd( pJson, 'pSourceDatabaseName', sSourceConnectionDetails );

sTargetDatabaseParameterType = JsonType( pTargetDatabaseName );
IF( sTargetDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.session.start', 'pConnectionName', pTargetDatabaseName, 'pJson', pJson ); sTargetConnectionDetails = sBedrockReturnValue;
ELSE;
  sTargetConnectionDetails = pTargetDatabaseName;
ENDIF;
pJson = JsonAdd( pJson, 'pTargetDatabaseName', sTargetConnectionDetails );

sSourceURL = JsonToString( sSourceConnectionDetails, '/sURL' );
sTargetURL = JsonToString( sTargetConnectionDetails, '/sURL' );

### Authentication headers for requests to the source connection
sSrcAuthHeaders = '[]';
IF( JsonToString( sSourceConnectionDetails, '/sAuthHeader' ) @<> '' );
  sSrcAuthHeaders = JsonAdd( sSrcAuthHeaders, '', StringToJson( 'Authorization: ' | JsonToString( sSourceConnectionDetails, '/sAuthHeader' ) ) );
ELSEIF( JsonToString( sSourceConnectionDetails, '/sSID' ) @<> '' );
  sSrcAuthHeaders = JsonAdd( sSrcAuthHeaders, '', StringToJson( 'Cookie: ' | JsonToString( sSourceConnectionDetails, '/sSID' ) ) );
ENDIF;

### Authentication headers for requests to the target connection
sTgtAuthHeaders = '[]';
IF( JsonToString( sTargetConnectionDetails, '/sAuthHeader' ) @<> '' );
  sTgtAuthHeaders = JsonAdd( sTgtAuthHeaders, '', StringToJson( 'Authorization: ' | JsonToString( sTargetConnectionDetails, '/sAuthHeader' ) ) );
ELSEIF( JsonToString( sTargetConnectionDetails, '/sSID' ) @<> '' );
  sTgtAuthHeaders = JsonAdd( sTgtAuthHeaders, '', StringToJson( 'Cookie: ' | JsonToString( sTargetConnectionDetails, '/sSID' ) ) );
ENDIF;

### If errors occurred terminate process with a major error status ###
IF( JsonSize( sMessages, '/Error' ) <> 0 );
  IF( pStrictErrorHandling = 1 );
    ProcessQuit;
  ELSE;
    ProcessBreak;
  ENDIF;
ENDIF;

#EndRegion - Validate Parameters

#Region - Execute Process Remotely

# Check if the process exists on the target. pJson is not forwarded here, so that a 404 is
# not treated as an error when pStrictErrorHandling = 1.
ExecuteProcess( '}bedrock.process.execute_http_request',
  'pMethod',    'GET',
  'pURL',       sTargetURL | '/Processes(''' | URLEncode( pProcess ) | ''')?$select=Name',
  'pHeaders',   sTgtAuthHeaders,
  'pLogOutput', pLogOutput
);
nStatusCode = StringToNumber( JsonToString( sBedrockReturnValue, '/status_code' ) );

# If the process doesn't exist on the target, copy it from the source
IF( nStatusCode = 404 );
  ExecuteProcess( '}bedrock.migrate.process',
    'pProcess',               pProcess,
    'pSourceDatabaseName',    sSourceConnectionDetails,
    'pTargetDatabaseName',    sTargetConnectionDetails,
    'pIncludeControlObjects', 1,
    'pLogOutput',             pLogOutput,
    'pStrictErrorHandling',   pStrictErrorHandling
  );
ENDIF;

# Reshape pProcessParameters for tm1.ExecuteWithReturn
sReshapedParameters = IF( JsonSize( pProcessParameters ) > 0, '{"Parameters":[]}', '' );
WHILE( JsonSize( pProcessParameters ) > 0 );
  sKey = JsonGetKey( pProcessParameters, 0 );
  sReshapedParameters = JsonAdd( sReshapedParameters, '/Parameters/0', '{"Name": '|StringToJson( sKey )|', "Value": '|JsonGet( pProcessParameters, sKey )|'}' );
  pProcessParameters = JsonRemove( pProcessParameters, sKey );
END;

# Execute the process on the target database
ExecuteProcess( '}bedrock.process.execute_http_request',
  'pMethod',  'POST',
  'pURL',     sTargetURL | '/Processes(''' | URLEncode( pProcess ) | ''')/tm1.ExecuteWithReturn?$expand=*',
  'pBody',    sReshapedParameters,
  'pHeaders', JsonAdd( sTgtAuthHeaders, '', '"Accept: application/json;odata.metadata=none"' ),
  'pJson',    pJson
);
sResponse = sBedrockReturnValue;

# Simplify ErrorLogFile to just its file name, when there is one
IF( JsonType( JsonGet( sResponse, '/body/ErrorLogFile' ) ) @= 'object' );
  sResponse = JsonPatch( sResponse, '[{"op": "move", "from": "/body/ErrorLogFile/Filename", "path": "/body/ErrorLogFile"}]' );
ENDIF;

#EndRegion - Execute Process Remotely

#Region - Cleanup

# Close sessions this process opened
IF( sSourceDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.process.execute_http_request', 'pMethod', 'POST', 'pURL', sSourceURL | '/ActiveSession/tm1.Close', 'pHeaders', sSrcAuthHeaders );
ENDIF;
IF( sTargetDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.process.execute_http_request', 'pMethod', 'POST', 'pURL', sTargetURL | '/ActiveSession/tm1.Close', 'pHeaders', sTgtAuthHeaders );
ENDIF;

sBedrockReturnValue = sResponse;

#EndRegion - Cleanup
#################################################################################################
